def png(i):
    return base64.b64encode(deck[i].get_pixmap(dpi=120).tobytes("png")).decode()


def ul(x):
    return "<ul>" + "".join(f"<li>{a}</li>" for a in x) + "</ul>"


parts = ["<h1>Nauka do prezentacji</h1><p class='m'>4 slajdy, około 5–10 minut. Przy każdym: co widać, co mówisz, co z tego wynika, pojęcia i możliwe pytania.</p>"
         "<div class='k'><b>Jedno zdanie na start:</b> sprawdzamy, czy da się oszacować wyświetlenia postów lepiej niż stałą razy obserwujący, i czy to działa tam, gdzie platforma ich nie podaje.</div>"]
for i, s in enumerate(SLIDES):
    parts.append(f"<section><h2>{s['t']}</h2><img src='data:image/png;base64,{png(i)}'><h3>Co jest na slajdzie</h3>{ul(s['see'])}<h3>Co mówisz</h3>" + "".join(f"<p>{p}</p>" for p in s["say"]) + f"<h3>Co z tego wynika</h3><div class='k'>{ul(s['so'])}</div><h3>Pojęcia</h3>" + "".join(f"<p><b>{a}:</b> {b}</p>" for a, b in s["terms"]) + "<h3>Możliwe pytania</h3>" + "".join(f"<p class='q'>{a}</p><p>{b}</p>" for a, b in s["qa"]) + "</section>")
css = """@page{size:125mm 222mm;margin:8mm}body{font:12.5pt/1.45 -apple-system,Helvetica,Arial,sans-serif;color:#1c1c1c;margin:0}h1{font-size:21pt;margin:0 0 6px}h2{font-size:16pt;margin:0 0 8px;color:#2f6f93}h3{font-size:10pt;text-transform:uppercase;letter-spacing:.05em;color:#2f6f93;margin:14px 0 4px;break-after:avoid}p{margin:0 0 7px}ul{margin:0 0 6px;padding-left:16px}li{margin-bottom:4px}img{width:100%;border:1px solid #ddd;border-radius:4px}section{break-before:page}.k{background:#eef3f6;border-radius:6px;padding:8px 10px;margin:8px 0}.k ul{margin:0}.m{color:#5f5f5c}.q{font-weight:700;margin-top:9px;margin-bottom:2px;break-after:avoid}"""
pathlib.Path(sys.argv[1]).write_text(f"<!doctype html><html lang='pl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Nauka do prezentacji</title><style>{css}</style></head><body>{''.join(parts)}</body></html>")
md = ["# Tekst do slajdów na zajęcia\n\nRoboczy tekst do `pitchdeck/class_pl.pdf`. To nie jest tekst preprintu. Warto powiedzieć go własnymi słowami. Pełna wersja do nauki: `pitchdeck/study_build.py`.\n"]
for s in SLIDES: md.append(f"## {s['t']}\n\n" + "\n\n".join(s["say"]) + "\n\n**Co z tego wynika:**\n" + "\n".join(f"- {x}" for x in s["so"]) + "\n")
(ROOT / "docs" / "pl" / "class_slides_script.md").write_text("\n".join(md)); print("ok")
